-- Secrets of connections that were revoked under Phase 2 were left `deleted`; make them terminal.
-- Done after the new status check is in place and before the trigger exists. Phase 2 deleted the
-- versions and cleared the pointer when it revoked a connection; if any is still there, fail
-- loudly instead of marking a secret terminal while its ciphertext remains.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "vault_secrets" AS s
    JOIN "connections" AS c ON c."id" = s."connection_id"
    WHERE c."status" = 'revoked'
      AND (s."active_version_id" IS NOT NULL
           OR EXISTS (SELECT 1 FROM "vault_secret_versions" AS v WHERE v."secret_id" = s."id"))
  ) THEN
    RAISE EXCEPTION '0005_phase3_vault: a revoked connection still has a vault secret with an active version or stored version rows; Phase 2 revocation should have deleted them, delete them and run the migration again'
      USING ERRCODE = 'data_exception';
  END IF;
END;
$$;
