CREATE FUNCTION "vault_secrets_revoked_is_terminal"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status = 'revoked' AND NEW.status <> 'revoked' THEN
    RAISE EXCEPTION 'vault_secrets: a revoked secret can never change status again'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'revoked' AND NEW.active_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'vault_secrets: a revoked secret has no active version'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "vault_secrets_revoked_is_terminal"
  BEFORE UPDATE ON "vault_secrets"
  FOR EACH ROW EXECUTE FUNCTION "vault_secrets_revoked_is_terminal"();
