CREATE FUNCTION "vault_secret_versions_refuse_revoked_secret"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "vault_secrets" WHERE "id" = NEW.secret_id AND "status" = 'revoked') THEN
    RAISE EXCEPTION 'vault_secret_versions: no version may be stored for a revoked secret'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
